# -*- coding: utf-8 -*-
from lib import *

RS = ['white-label-account-recovery', 'how-white-label-account-recovery-works']

mk('agency-client-confidentiality-account-recovery', 'Client confidentiality', 'ops',
 'Client Confidentiality in White Label Recovery',
 'How client details are handled when an agency uses a recovery partner: what to share, what to hold back and how to raise an NDA.',
 'Client confidentiality in white label account recovery.',
 'Your clients do not know Unbanz, and that is how the arrangement is meant to work. Here is how to handle their details sensibly.',
 'In white label recovery, your clients do not know Unbanz, and Unbanz works only with your agency. Share the least that the appeal needs: the username, the notice and its date. You do not need to name the client. If you want a non-disclosure agreement, raise it before sending anything.',
 [('Share the minimum', 'Username, notice, date. Nothing more is needed to start.'),
  ('One contact', 'Unbanz speaks to your agency only, never to your client.'),
  ('Raise terms early', 'If you need an NDA or other terms, agree them before work starts.')],
 [('model', 'How the arrangement is meant to work',
   P('Unbanz works for the agency, behind the scenes, under the agency’s brand. The agency keeps the client relationship. Unbanz does not contact the agency’s clients and does not mention them elsewhere. The agency decides what its client is told.')),
  ('table', 'What to share and what to hold back',
   TABLE(['Usually needed', 'Usually not needed'],
         [['Username or profile link', 'The client’s name or company'],
          ['Screenshot of the notice and its date', 'Contracts or campaign plans'],
          ['The email and number on the account, if a check is likely', 'Payment details of the client'],
          ['The type of business, when it matters to the notice', 'Other accounts the client holds']])),
  ('platform', 'What the platform will still send the client',
   P('The platform sends its own emails, codes and identity checks to the account owner. Those come from the platform, not from Unbanz, and no one at Unbanz asks for them. Tell your client to expect them and to complete any identity check themselves. See [[what-your-client-sees-white-label-recovery|what your client sees]].')),
  ('nda', 'Raising an NDA',
   P('Some agencies need a non-disclosure agreement for client work. This is a matter to agree between the two companies. Raise it before you send any client detail, and ask Unbanz in writing. This page is not legal advice, and any document should be reviewed by your own lawyer.')),
  ('own', 'Your own side of confidentiality',
   UL(['Check your own client contracts for anything about subcontractors, and add a line if needed.', 'Keep notice screenshots in a folder with limited access.', 'Delete material you no longer need when a matter closes.', 'Never post a client’s account problem in a public group.']) +
   P('A plain clause for your terms is in [[client-terms-account-recovery-clause|what to put in your client terms]].'))],
 [('Does Unbanz contact my clients?', 'No. Unbanz works only with your agency and never contacts your clients.'),
  ('Do I have to name the client?', 'No. The username, the notice and the date are enough to start.'),
  ('Can we sign an NDA?', 'Raise it before you send any detail. It is a matter to agree between the two companies, and your own lawyer should review any document.'),
  ('Will the platform’s emails reveal Unbanz?', 'No. The platform sends its own emails and checks to the account owner. They do not mention Unbanz.'),
  ('Is this legal advice?', 'No. It is general information for planning your own process.')],
 RS + ['agency-account-recovery-red-flags', 'client-terms-account-recovery-clause', 'what-your-client-sees-white-label-recovery'],
 'Confidentiality in white label recovery: what to share, what to hold back, NDAs.')

mk('how-to-tell-client-account-disabled-template', 'How to tell a client their account is disabled', 'ops',
 'How to Tell a Client Their Account Is Disabled',
 'A plain script and message templates for telling a client their Instagram or Facebook account is disabled, without promising an outcome.',
 'How to tell a client their account is disabled.',
 'Bad news lands better when it is short, calm and clear about what happens next. Here are the words.',
 'When a client’s account is disabled, tell them three things: what happened, what you are doing and what you cannot promise. Keep it short and calm, ask for the notice screenshot, and warn them not to try random logins. Never promise a result, because the platform decides.',
 [('Calm and short', 'Long messages sound like panic.'),
  ('Next step first', 'Lead with what you are doing.'),
  ('No promises', 'The platform decides, and your message should say so.')],
 [('script', 'A three-part script',
   OL(['What happened: the account is disabled or restricted, and the platform sent a notice.', 'What you are doing: starting the official recovery process and gathering the details.', 'What you cannot promise: the platform decides, and you will report each step.'])),
  ('t1', 'Message one: first reply',
   TMPL('First reply', 'I have seen the notice. I am starting the recovery process today. Please send a screenshot of the notice and the date it appeared. Do not try different logins and do not share any codes with anyone. I will update you as soon as I have news. The platform makes the final decision, so I cannot promise an outcome.')),
  ('t2', 'Message two: when the client is panicking',
   TMPL('Panicking client', 'I understand this is stressful. Nothing is lost yet. The best thing you can do is wait and avoid new login attempts, which can make things harder. I will handle the process and keep you updated. I cannot promise how it ends, but I will tell you everything I learn.')),
  ('t3', 'Message three: bad news',
   TMPL('When the platform says no', 'The platform has given its decision and it has not been restored. That decision is final for this request. I am sorry. Here is what we can do next: set up a new account properly, move your content to other channels and make sure this does not happen again.')),
  ('dont', 'Words to avoid',
   UL(['“Definitely”, “for sure” or any promise about the result.', '“I know someone at Meta.”', '“It will be back by Friday.”', 'Blaming the client for what happened before you know the cause.']) +
   P('More templates are in [[client-status-update-templates-account-recovery|the status update templates]].'))],
 [('What should I say first to a client with a disabled account?', 'Tell them what you are doing, ask for the screenshot and date, and tell them not to try random logins or share codes.'),
  ('Should I give the client a timeframe?', 'No. The platform decides the timing and the result, so any date you give may be wrong.'),
  ('How do I deliver bad news?', 'Be direct, say the decision is final for that request, and offer clear next steps.'),
  ('Do I tell the client a partner is involved?', 'That is your choice. If the client asks directly, answer honestly.'),
  ('Can I copy these templates?', 'Yes. Change the wording to sound like you.')],
 RS + ['client-status-update-templates-account-recovery', 'what-your-client-sees-white-label-recovery', 'white-label-recovery-for-social-media-agencies'],
 'A script and message templates for telling a client their account is disabled.')

mk('client-status-update-templates-account-recovery', 'Client status update templates', 'ops',
 'Client Status Update Templates for Recovery',
 'Copy-ready status messages for clients during an account recovery request: started, waiting, needs action, decision received.',
 'Client status update templates for account recovery.',
 'A client who hears nothing assumes the worst. Short, regular updates keep trust, even when there is no news.',
 'During an account recovery request, send the client a short update at each step: started, waiting, action needed and decision received. State what has happened, what comes next and what you cannot promise. No dates for the platform’s decision, and no claims about the result.',
 [('Regular beats long', 'A short note at each step is enough.'),
  ('Name the next step', 'Clients relax when they know what happens next.'),
  ('Never predict', 'Say what you know and stop there.')],
 [('started', 'Started',
   TMPL('Request started', 'The recovery request has been started. I have the notice and the date, and the appeal is being prepared. Next, I will tell you when it has been filed. I cannot predict the platform’s decision.')),
  ('filed', 'Filed',
   TMPL('Request filed', 'The request has been filed with the platform. They decide the timing and the result. There is nothing you need to do right now. Please do not try new logins or file your own request, which can create conflicts.')),
  ('action', 'Action needed from the client',
   TMPL('Client action', 'The platform has asked for something that only you can do, an identity check. Please complete it from the device you normally use, and send me a screenshot when done. Do not share any codes with anyone, including me.')),
  ('waiting', 'Waiting',
   TMPL('Still waiting', 'No decision yet. I have checked and nothing has changed. I will update you again at the next step, or sooner if the platform responds. I cannot give a date, because the platform decides.')),
  ('decision', 'Decision received',
   TMPL('Positive', 'The platform has restored access. Please change your password now, turn on an authenticator app and check recent activity. I will send a short checklist.') +
   TMPL('Negative', 'The platform’s decision is that the account stays closed. This is final for this request. I am sorry. I would suggest we plan what comes next, including a new account set up properly and keeping your audience through other channels.')),
  ('rules', 'Rules for every update',
   UL(['Use plain words and your own voice.', 'Never include anything that suggests a partner’s name unless you choose to.', 'Do not share the platform’s private emails by forwarding them blindly.', 'Keep a log of what you sent and when.']) +
   P('See also [[how-to-tell-client-account-disabled-template|how to tell a client their account is disabled]].'))],
 [('How often should I update a client?', 'At each step, and when asked. A short note saying there is no news is better than silence.'),
  ('Should updates include dates?', 'Only dates you control. Never give a date for the platform’s decision.'),
  ('What if the client asks for proof of progress?', 'Share what you can, such as that the request has been filed, without exposing anything private about the partner.'),
  ('What if the answer is no?', 'Say it plainly, say it is final for that request and give next steps.'),
  ('Can I reuse the templates?', 'Yes. Rewrite them in your own voice.')],
 RS + ['how-to-tell-client-account-disabled-template', 'agency-onboarding-checklist-white-label-partner', 'agency-intake-form-checklist-account-recovery'],
 'Copy-ready status messages from request start to decision.')

mk('agency-intake-form-checklist-account-recovery', 'Agency intake checklist', 'ops',
 'Agency Intake Checklist for Recovery Requests',
 'The details to collect from a client before you pass an account recovery request to a partner, and what never to ask for.',
 'Agency intake checklist for account recovery requests.',
 'A clean intake saves days of back and forth. This is the list to collect before you contact a recovery partner.',
 'Before passing a recovery request to a partner, collect the platform, the username, a screenshot of the notice with its date, the email and number on the account, who else has access and the client’s go-ahead. Never ask for a password or a login code, under any circumstances.',
 [('One list', 'The same questions for every client.'),
  ('Facts over stories', 'The notice and the date matter more than a long explanation.'),
  ('Never a password', 'Passwords and codes stay with the client.')],
 [('list', 'The checklist',
   TABLE(['Field', 'Why it is needed'],
         [['Platform and account type', 'Instagram, Facebook, ad account, Snapchat, other'],
          ['Username or profile link', 'Identify the account'],
          ['Screenshot of the notice', 'Shows the exact wording'],
          ['Date the notice appeared', 'Helps the appeal'],
          ['Email and phone number on the account', 'May be used for checks'],
          ['Who else has access', 'Admins, editors, partners'],
          ['Connected assets', 'Pages, ad accounts, business portfolio'],
          ['What happened just before', 'Context for the request'],
          ['Whether any appeal was filed already', 'Avoid conflicting requests'],
          ['The client’s go-ahead', 'Needed before anyone acts']])),
  ('never', 'What never to ask for',
   UL(['A password.', 'A login code or recovery code.', 'Access to the client’s email.', 'A payment card.']) +
   P('If a provider asks for any of these, see [[agency-account-recovery-red-flags|red flags for agencies]].')),
  ('how', 'How to ask',
   P('Use a form, an email or a short chat message with the list. A client under stress does better with a clear list than with an open question. If the client cannot find a field, tell them to skip it and send what they have.')),
  ('send', 'Sending it to Unbanz',
   P('Send the details on WhatsApp +1 934 201 2490 or by email to team@unbanz.com. No client name is needed. Unbanz replies with the route and what to expect, and does not contact the client.')),
  ('storage', 'Keeping the material tidy',
   P('Store the screenshots and the date in a folder named after the matter, not the client. Delete them when the matter is closed. See [[agency-client-confidentiality-account-recovery|client confidentiality]].'))],
 [('What is the minimum needed to start?', 'The platform, the username, a screenshot of the notice with the date and the client’s go-ahead.'),
  ('Why do you need the email and phone number?', 'The platform may send checks to them, and the details help identify the account. Passwords are never needed.'),
  ('What if the client has no screenshot?', 'Ask them to describe the notice word for word and to try to capture it again, without logging in repeatedly.'),
  ('Do I need the client’s name?', 'No.'),
  ('Can I use my own form?', 'Yes. Keep the fields the same.')],
 RS + ['account-recovery-sop-template-for-agencies', 'agency-onboarding-checklist-white-label-partner', 'client-status-update-templates-account-recovery'],
 'The intake checklist for passing a recovery request to a partner.')

mk('account-recovery-sop-template-for-agencies', 'Recovery SOP template', 'ops',
 'Account Recovery SOP Template for Agencies',
 'A standard operating procedure your team can copy: roles, steps, templates and rules for handling a client account lockout with a partner.',
 'Account recovery SOP template for agencies.',
 'When a lockout happens, nobody should be inventing the process. Here is a plain procedure to adapt.',
 'An account recovery SOP for an agency sets one owner per incident, a fixed intake list, a handoff step to the partner, a client update rhythm and a close-out checklist. It does not promise outcomes. Copy the structure below and adjust names and tools to your team.',
 [('One owner', 'One person leads each incident.'),
  ('Fixed steps', 'Same steps every time.'),
  ('No promises', 'The SOP states that the platform decides.')],
 [('purpose', 'Purpose and scope',
   P('This procedure covers disabled, suspended, locked or hacked social and ad accounts managed for clients. It sets who does what from the first report to the close-out. It does not cover legal disputes or payment disputes.')),
  ('roles', 'Roles',
   TABLE(['Role', 'Responsibility'],
         [['Incident owner', 'Leads the matter, talks to the client, sends details to the partner'],
          ['Account manager', 'Keeps the wider client relationship informed'],
          ['Media buyer or content lead', 'Pauses campaigns and scheduled posts'],
          ['Partner', 'Prepares and files the request, reports back to the incident owner only']])),
  ('steps', 'Steps',
   OL(['Log the report and name an incident owner.', 'Pause scheduled posts and ads that depend on the account.', 'Collect the details using the [[agency-intake-form-checklist-account-recovery|intake checklist]].', 'Send the details to the partner.', 'Send the first client update using the [[client-status-update-templates-account-recovery|templates]].', 'Update the client at each step.', 'On decision, tell the client and agree next steps.', 'Close the matter and run the prevention review.'])),
  ('rules', 'Rules',
   UL(['No passwords or codes are requested or stored.', 'No new accounts are opened to avoid a restriction.', 'No promises about outcomes or dates.', 'No third party is told about the matter without the client’s go-ahead.'])),
  ('close', 'Close-out checklist',
   UL(['The log shows each step with dates.', 'Notice screenshots are stored in the matter folder and deleted at the set time.', 'Admins, recovery email and two-factor status were reviewed.', 'The client received the prevention checklist.']) +
   P('Use [[prevent-client-account-lockouts-agency-checklist|the prevention checklist]] for the last step.'))],
 [('Why have an SOP?', 'It removes guesswork during a stressful moment and makes handoffs consistent.'),
  ('Who should be the incident owner?', 'Usually the account manager or the person who knows the client best.'),
  ('Does the SOP need legal review?', 'Have your own lawyer look at any client-facing wording.'),
  ('Can I add more steps?', 'Yes. Keep the rules section the same.'),
  ('Where does the partner fit?', 'The partner only talks to the incident owner and never to the client.')],
 RS + ['agency-intake-form-checklist-account-recovery', 'agency-onboarding-checklist-white-label-partner', 'prevent-client-account-lockouts-agency-checklist'],
 'A plain SOP template: roles, steps, rules and close-out.')

mk('agency-onboarding-checklist-white-label-partner', 'Partner onboarding checklist', 'ops',
 'White Label Partner Onboarding Checklist',
 'What an agency should settle before the first recovery request: contacts, terms, intake, client wording and a test run.',
 'Agency onboarding checklist for a white label partner.',
 'Set things up before the first emergency. An hour of preparation makes the first lockout calm.',
 'Before the first recovery request, an agency should agree terms with the partner, name who sends requests, prepare the intake checklist, write its client wording and decide how it will price. A short test run with a past lockout shows gaps. The partner does not contact clients.',
 [('Prepare once', 'Do the setup before any client needs it.'),
  ('Name the contacts', 'Decide who sends requests and who approves them.'),
  ('Practise', 'Walk through a past lockout on paper.')],
 [('steps', 'The checklist',
   OL(['Message Unbanz on WhatsApp +1 934 201 2490 or by email to team@unbanz.com and say what your agency does.', 'Agree the terms in writing before any request is sent.', 'Decide who in your team may send requests, and who approves.', 'Ask any NDA question now, not mid-incident. See [[agency-client-confidentiality-account-recovery|client confidentiality]].', 'Prepare the [[agency-intake-form-checklist-account-recovery|intake checklist]].', 'Adopt the [[client-status-update-templates-account-recovery|status templates]].', 'Decide how you price. See [[agency-pricing-models-reselling-recovery|pricing models]].', 'Add a line to your client terms. See [[client-terms-account-recovery-clause|client terms]].', 'Run a dry test with a past lockout.'])),
  ('table', 'Who decides what',
   TABLE(['Decision', 'Who'],
         [['Whether to take on the request', 'The agency'],
          ['What to say to the client', 'The agency'],
          ['Which official route fits', 'The partner, with the agency’s input'],
          ['The outcome', 'The platform']])),
  ('test', 'The dry run',
   P('Pick a past lockout and fill out the intake checklist as if it were new. Note anything you could not answer. Those are your onboarding gaps, and it is cheaper to find them now.')),
  ('client', 'Preparing your clients',
   P('Add an account security step to your client onboarding: admin list, backup email, authenticator app. See [[prevent-client-account-lockouts-agency-checklist|the prevention checklist]].'))],
 [('How do we start working with Unbanz?', 'Message Unbanz on WhatsApp or by email, tell us what your agency does and agree terms before any request.'),
  ('Do we need a contract?', 'Terms are agreed before work starts. Ask for them in writing.'),
  ('How many people should send requests?', 'Keep it to one or two, so details do not get duplicated.'),
  ('Can we test the process first?', 'Yes. Run a dry run on paper using a past lockout.'),
  ('Will Unbanz contact our clients?', 'No.')],
 RS + ['become-a-white-label-recovery-partner', 'account-recovery-sop-template-for-agencies', 'agency-intake-form-checklist-account-recovery'],
 'Onboarding checklist for agencies starting with a white label partner.')

mk('agency-pricing-models-reselling-recovery', 'Pricing models for reselling recovery', 'ops',
 'Pricing Models for Reselling Account Recovery',
 'Common ways agencies price account recovery for their own clients: per incident, add-on, retainer line or included. Pros, cons and what to avoid.',
 'Pricing models for reselling account recovery.',
 'There is no single right way to charge for recovery. These are the usual models, with what each one means for you.',
 'Agencies usually resell account recovery in one of four ways: per incident, as a monthly protection add-on, as a line inside a retainer, or included in a package. Each shifts risk differently. Whatever the model, price the work and coordination, never a promised outcome, because the platform decides.',
 [('Four common models', 'Per incident, add-on, retainer line, included.'),
  ('Price the work', 'Not the outcome.'),
  ('No numbers here', 'Pricing depends on your market and costs. Agree it with your partner.')],
 [('models', 'The four models',
   TABLE(['Model', 'How it works', 'Good for'],
         [['Per incident', 'Client pays when a lockout happens', 'Agencies who rarely see lockouts'],
          ['Monthly add-on', 'Client pays a small recurring amount for protection and handling', 'Agencies with many active accounts'],
          ['Retainer line', 'Recovery handling is a named line in the retainer', 'Larger clients'],
          ['Included', 'Absorbed as a service benefit', 'Agencies using it to retain clients']])),
  ('risk', 'Where the risk sits',
   P('Under per incident pricing, the client carries the cost when it happens. Under add-ons and included models, the agency carries the cost of unlucky months. Choose the model that suits your cash flow and how much risk you want. The partner’s terms feed into this.')),
  ('principles', 'Principles that apply to all',
   UL(['Price the effort, intake, coordination and communication.', 'Say clearly that the platform decides and nothing is promised.', 'State what happens if the account is not restored, so there are no surprises.', 'Keep a written record of what was agreed with the client.', 'For username claims, remember our refund policy of a 100% refund if a claim fails, and agree how you pass that through.'])),
  ('avoid', 'What not to do',
   UL(['Do not price against the result, such as success fees promising recovery.', 'Do not advertise a fixed outcome.', 'Do not hide that the work is done with a partner if the client asks.'])),
  ('next', 'Next',
   P('For how to work out your own number without promising outcomes, read [[how-to-price-account-recovery-for-agencies|how to price account recovery for agencies]]. Terms for the client are in [[client-terms-account-recovery-clause|client terms]].'))],
 [('Which pricing model is best?', 'It depends on how many accounts you manage and how much risk you want to carry. Per incident is the simplest to start with.'),
  ('Should I charge a success fee?', 'Avoid anything that implies the result is certain. Charge for the work, and keep the platform’s decision separate.'),
  ('Does Unbanz set my client price?', 'No. You set your own price. Unbanz agrees its own terms with you.'),
  ('What if recovery fails?', 'Say in advance what the client pays and what they do not.'),
  ('Does this page give prices?', 'No. Prices depend on your market and your costs.')],
 RS + ['how-to-price-account-recovery-for-agencies', 'client-terms-account-recovery-clause', 'become-a-white-label-recovery-partner'],
 'Four ways agencies price recovery, and where the risk sits.')

mk('how-to-price-account-recovery-for-agencies', 'How to price recovery', 'ops',
 'How to Price Recovery Without Outcome Promises',
 'A method for working out your price for recovery work that is honest about uncertainty, covers your costs and avoids success promises.',
 'How to price account recovery without promising outcomes.',
 'You are selling effort and handling, not a result you do not control. Here is a method that keeps the price honest.',
 'Price account recovery by working out your costs and the effort you put in: intake, coordination, partner terms and client communication. Do not price the outcome, because the platform decides. State clearly what the client pays if the account is not restored, and put it in writing.',
 [('Start from your costs', 'Time, partner terms and communication.'),
  ('Price the work', 'Not the outcome.'),
  ('Write the rules', 'What if it fails? Put the answer in the quote.')],
 [('steps', 'A pricing method',
   OL(['List what you do: intake, coordination, updates, handoff, follow-up.', 'Estimate your own time for each in a normal matter.', 'Add the partner’s terms.', 'Add a margin that fits your business.', 'Decide what happens if the account is not restored and put it in the quote.', 'Check that nothing in the wording promises a result.'])),
  ('table', 'What goes into your cost',
   TABLE(['Part', 'Question'],
         [['Your time', 'How long does a normal incident take you?'],
          ['The partner', 'What are the terms you agreed?'],
          ['Risk', 'What do you absorb if the account is not restored?'],
          ['Margin', 'What does your agency need to earn from this line?']])),
  ('quote', 'What a quote should say',
   UL(['What you will do: start the official process with a specialist and keep the client updated.', 'What you will not do: promise a result or a date.', 'What the client pays in each situation, including if the result is a refusal.', 'That the platform makes the final decision.']) +
   TMPL('Wording for a quote', 'This quote covers starting the official recovery process, preparing the request through a specialist and keeping you updated. The platform decides the result and the timing, and we cannot promise either. The fee is for the work and does not depend on the decision.')),
  ('why', 'Why not a success fee',
   P('A success fee tempts people to overpromise, and it can push towards shortcuts. It also makes the client read the fee as a promise. An effort-based price is easier to explain and keeps everyone honest.')),
  ('more', 'More',
   P('Read [[agency-pricing-models-reselling-recovery|pricing models]] and [[client-terms-account-recovery-clause|client terms]] too.'))],
 [('How do I decide my price?', 'Start from your own time, the partner’s terms and the risk you carry, then add a margin.'),
  ('Should the price depend on success?', 'It is cleaner not to. The platform decides, and a price tied to results invites overpromising.'),
  ('What should I tell the client if it fails?', 'Say so in the quote beforehand: what they pay and what they do not.'),
  ('Do you provide price numbers on this page?', 'No. Prices depend on your market and costs.'),
  ('Can Unbanz help set my price?', 'Unbanz can explain its own terms. Your client price is your decision.')],
 RS + ['agency-pricing-models-reselling-recovery', 'client-terms-account-recovery-clause', 'white-label-recovery-for-community-managers-freelancers'],
 'A method for pricing recovery work without promising outcomes.')

mk('client-terms-account-recovery-clause', 'Client terms for recovery', 'ops',
 'Client Terms for Account Recovery Help',
 'Plain points for your client agreements about account recovery help: scope, no promised outcome, client duties and partner use. Not legal advice.',
 'What to put in your client terms about account recovery.',
 'A few clear lines in your agreement prevent most arguments later. These are plain points to raise with your lawyer.',
 'Client terms about account recovery should state what you do, that the platform decides the outcome, what the client must do, how information is handled and that a specialist partner may be used. This page lists plain points to discuss with your own lawyer. It is not legal advice.',
 [('Scope', 'What you will and will not do.'),
  ('No promised outcome', 'The platform decides.'),
  ('Client duties', 'Be reachable, never share codes, complete checks.')],
 [('points', 'Points to cover',
   UL(['Scope: you will start the official recovery process and keep the client informed.', 'Outcome: the platform decides, and no result or date is promised.', 'Client duties: provide accurate information, complete identity checks themselves, never share passwords or codes with the agency.', 'Third parties: you may use a specialist partner and share the information needed.', 'Fees: what is charged for the work, and what happens if the account is not restored.', 'Ownership: the account belongs to the client, and you act only with their go-ahead.'])),
  ('sample', 'Sample wording to adapt',
   TMPL('Not legal advice', 'If an account managed under this agreement is disabled, restricted or locked, the agency will begin the platform’s official recovery process on the client’s behalf and keep the client informed. The platform makes the final decision. The agency does not promise any result or timing. The agency may use specialist partners and share only the information needed. The client will complete any identity checks themselves.')),
  ('lawyer', 'Have a lawyer look at it',
   P('Laws on contracts differ by country, and so do rules on data. Use the sample as a conversation starter, and have your own lawyer adapt it. Nothing here is legal advice.')),
  ('data', 'Data points',
   P('If you share client details with a partner, say so in your terms or privacy notice and share the minimum needed. See [[agency-client-confidentiality-account-recovery|client confidentiality]].')),
  ('link', 'Related',
   P('For pricing, see [[how-to-price-account-recovery-for-agencies|how to price recovery]]. For the full routine, see [[account-recovery-sop-template-for-agencies|the SOP template]].'))],
 [('Do I need a recovery clause in client terms?', 'It helps. It makes clear what you do and do not promise before a lockout happens.'),
  ('Is the sample wording legal advice?', 'No. It is a starting point for your own lawyer.'),
  ('Do I have to say a partner is used?', 'Check what your local rules and contracts require.'),
  ('What should the clause say about outcomes?', 'That the platform decides and no result or date is promised.'),
  ('Does Unbanz provide legal templates?', 'No. Ask your own lawyer.')],
 RS + ['agency-client-confidentiality-account-recovery', 'agency-pricing-models-reselling-recovery', 'account-recovery-sop-template-for-agencies'],
 'Plain points for client terms about recovery. Not legal advice.')

mk('prevent-client-account-lockouts-agency-checklist', 'Lockout prevention checklist', 'ops',
 'How Agencies Can Prevent Client Account Lockouts',
 'A practical checklist to cut the odds and the damage of client account lockouts: admins, backup email, authenticator, roles and records.',
 'How agencies can prevent client account lockouts.',
 'Not every lockout can be avoided, but most of the damage can. This is the checklist to run at onboarding and once a quarter.',
 'To reduce client account lockouts, agencies should make sure the client owns every account, add a second admin, use an authenticator app instead of text messages, store backup codes safely, use a recovery email the client controls and keep a record of roles. These steps cannot prevent every platform decision.',
 [('Ownership', 'The client owns the account. The agency has roles.'),
  ('Two of everything', 'Two admins, two ways to prove identity.'),
  ('Check regularly', 'Run it at onboarding and every quarter.')],
 [('list', 'The checklist',
   OL(['The client business owns the business portfolio, Pages and ad accounts.', 'There are at least two full admins from the client side or trusted agency staff.', 'Two-factor authentication uses an authenticator app.', 'Backup codes are saved in a safe place, not in the same email.', 'The recovery email is on the client’s own domain and the client controls it.', 'The phone number on the account is current.', 'Old collaborators and old agencies are removed.', 'Payment methods and business verification are up to date.', 'Account Quality is checked on a schedule.', 'Notice screenshots are kept, with dates.'])),
  ('why', 'Why each one matters',
   TABLE(['Item', 'What it prevents'],
         [['Client ownership', 'Disputes and delays if the agency relationship ends'],
          ['Second admin', 'A single lost login ending access'],
          ['Authenticator app', 'Lost access when a phone number changes or is hijacked'],
          ['Recovery email on own domain', 'Dependence on a free mailbox no one remembers'],
          ['Removing old collaborators', 'Unwanted access and confusion']])),
  ('limits', 'What the checklist cannot do',
   P('It does not stop the platform from disabling an account after an automated decision. It reduces the chance that a simple lost login becomes a crisis, and it gives you a complete record if an appeal is needed.')),
  ('onboard', 'Putting it into onboarding',
   P('Add the checklist to the first week with a new client. It also shows professional care. See [[agency-onboarding-checklist-white-label-partner|the partner onboarding checklist]] for the agency side.')),
  ('review', 'Quarterly review',
   P('Once a quarter, open each client’s accounts, check the roles, confirm the recovery email works and update the record.'))],
 [('Can lockouts be prevented completely?', 'No. The platform may still make decisions on its own. The checklist reduces the risk and the damage.'),
  ('Why use an authenticator app?', 'Text messages can be lost when a number changes or is hijacked. An authenticator app is more reliable.'),
  ('Who should own the accounts?', 'The client business, with the agency holding roles.'),
  ('How often should I review?', 'At onboarding and once a quarter.'),
  ('Where do I store backup codes?', 'In a password manager or a safe place that is separate from the account’s email.')],
 RS + ['agency-onboarding-checklist-white-label-partner', 'white-label-hacked-account-recovery', 'account-recovery-sop-template-for-agencies'],
 'The lockout prevention checklist for onboarding and quarterly reviews.')

mk('agency-account-recovery-red-flags', 'Red flags in recovery providers', 'ops',
 'Red Flags When an Agency Picks a Recovery Provider',
 'Warning signs to watch for before you trust a recovery provider with a client: promised results, password requests, inside contacts and more.',
 'Red flags when an agency picks a recovery provider.',
 'Your client’s account and your reputation both depend on who you hand the work to. These are the warning signs.',
 'Warning signs of a poor recovery provider: promised or certain results, requests for passwords or codes, claims of inside contacts at the platform, pressure to pay by gift card or crypto, talk of buying accounts and refusal to explain the process. If you see any of them, step away.',
 [('Promises', 'No one controls the platform’s decision.'),
  ('Passwords', 'A genuine provider never needs one.'),
  ('Pressure', 'Urgency and secrecy are signs of trouble.')],
 [('flags', 'The red flags',
   TABLE(['Red flag', 'Why it matters'],
         [['“Certain recovery” or sure results', 'The platform decides, so the claim is false'],
          ['Requests for a password or login code', 'Gives away access to the client’s account'],
          ['Claims of inside contacts at the platform', 'No outside provider has an inside route'],
          ['Offers to buy, sell or supply accounts', 'Against the rules and risky'],
          ['Payment by gift card or crypto only', 'Hard to trace and common in scams'],
          ['Talk of fake or mass reports', 'Breaks the rules and can backfire'],
          ['Cannot explain the process in plain words', 'Often means there is no process'],
          ['No clear refund policy where one applies', 'Leaves you carrying the loss']])),
  ('check', 'Questions to ask any provider',
   OL(['What routes do you use, in plain words?', 'What do you need from the client, and what never?', 'What do you do if the platform says no?', 'Do you contact my client?', 'How do you handle confidentiality?', 'What are the terms, in writing?'])),
  ('unbanz', 'How Unbanz answers these',
   P('Unbanz uses the platform’s official routes only, never asks for passwords or codes, makes no claims of inside contacts, does not buy or sell accounts, uses no fake or mass reports and promises no results. The refund policy applies to Instagram username claims: a 100% refund if a claim fails.')),
  ('what-next', 'If you already hit one',
   P('Stop sending details, change any passwords you shared and warn the client. Read [[how-to-choose-a-white-label-recovery-partner|how to choose a white label recovery partner]] for a fuller checklist.'))],
 [('What is the biggest red flag?', 'A promise of a certain result. No outside provider controls the platform’s decision.'),
  ('Should a provider ever need a password?', 'No. Passwords and login codes stay with the account owner.'),
  ('Is paying by gift card normal?', 'No. It is a common sign of a scam.'),
  ('What if a provider says they know someone inside Meta?', 'Walk away. It is not a legitimate route.'),
  ('How do I check a provider?', 'Ask the six questions on this page and get the terms in writing.')],
 RS + ['how-to-choose-a-white-label-recovery-partner', 'white-label-hacked-account-recovery', 'agency-client-confidentiality-account-recovery'],
 'Red flags and six questions to ask any recovery provider.')
